        [Conditional("ENABLE_UNITY_COLLECTIONS_CHECKS")]
        private void CheckRead()
        {
#if ENABLE_UNITY_COLLECTIONS_CHECKS
            if (IsCreated) AtomicSafetyHandle.CheckReadAndThrow(m_Safety);
#endif
        }
        [Conditional("ENABLE_UNITY_COLLECTIONS_CHECKS")]
        private void CheckWrite()
        {
#if ENABLE_UNITY_COLLECTIONS_CHECKS
            if (IsCreated) AtomicSafetyHandle.CheckWriteAndThrow(m_Safety);
#endif
        }

    }

    [NativeContainer]
    public unsafe partial struct NativeDeterministicStack<T> : IDisposable where T : unmanaged
    {
        internal NativeStorage<T> Storage;
#if ENABLE_UNITY_COLLECTIONS_CHECKS
        internal AtomicSafetyHandle m_Safety;
#endif

        public NativeDeterministicStack(int capacity, Allocator allocator) : this(new BufferOptions(capacity), allocator) { }
        public NativeDeterministicStack(BufferOptions options, Allocator allocator)
        {
            this = default;

            Storage = NativeStorage<T>.Create(options, allocator);

#if ENABLE_UNITY_COLLECTIONS_CHECKS
            m_Safety = AtomicSafetyHandle.Create();
            AtomicSafetyHandle.SetBumpSecondaryVersionOnScheduleWrite(m_Safety, true);
#endif
        }


        public DeterministicStatus TryPush(in T value)
        { CheckWrite(); return !IsCreated ? DeterministicStatus.Disposed : SequenceKernel<T, NativeStorage<T>>.TryInsert(ref Storage, ref Storage.Data->State, Storage.Data->State.Count, value); }
        public DeterministicStatus TryPeek(out T value)
        {
            CheckRead(); value = default;
            if (!IsCreated) return DeterministicStatus.Disposed;
            return Count == 0 ? DeterministicStatus.Empty : TryGet(Count - 1, out value);
        }
        public DeterministicStatus TryPop(out T value)
        {
            CheckWrite(); var status = TryPeek(out value); if (!status.IsSuccess()) return status;
            status = SequenceKernel<T, NativeStorage<T>>.TryRemoveAt(ref Storage, ref Storage.Data->State, Count - 1);
            if (!status.IsSuccess()) value = default; return status;
        }
        public DeterministicStatus TryClear()
        { CheckWrite(); return !IsCreated ? DeterministicStatus.Disposed : SequenceKernel<T, NativeStorage<T>>.TryClear(ref Storage, ref Storage.Data->State); }
        public void Push(T value) => NativeChecks.Status(TryPush(value));
        public T Pop() { var status = TryPop(out T value); NativeChecks.Status(status); return value; }
        public T Peek() { var status = TryPeek(out T value); NativeChecks.Status(status); return value; }
        public void Clear() => NativeChecks.Status(TryClear());



        public bool IsCreated => Storage.IsCreated;
        public int Count { get { CheckRead(); return IsCreated ? Storage.Data->State.Count : 0; } }
        public int Capacity { get { CheckRead(); return Storage.Capacity; } }
        public DeterministicStatus TryGet(int index, out T value)
        {
            CheckRead(); value = default;
            return !IsCreated ? DeterministicStatus.Disposed : Storage.BatchActive ? DeterministicStatus.Invalidated
                : SequenceKernel<T, NativeStorage<T>>.TryGet(ref Storage, Storage.Data->State, index, out value);
        }
        public DeterministicStatus TryCapture(out NativeSequenceSnapshot<T> snapshot)
        {
            CheckWrite(); snapshot = default;
            var status = Storage.TryCapture(out int slot, out ulong lease); if (!status.IsSuccess()) return status;
            snapshot = new NativeSequenceSnapshot<T> { Storage = Storage, State = Storage.Data->State, Slot = slot, Lease = lease, Ring = false };
#if ENABLE_UNITY_COLLECTIONS_CHECKS
            snapshot.m_Safety = m_Safety;
#endif
            return DeterministicStatus.None;
        }
        public DeterministicStatus TryRestore(in NativeSequenceSnapshot<T> snapshot)
        {
            CheckWrite();
            if (!IsCreated) return DeterministicStatus.Disposed;
            if (snapshot.Storage.Data != Storage.Data || snapshot.Ring != false) return DeterministicStatus.InvalidOwner;
            var status = Storage.TryRestore(snapshot.Slot, snapshot.Lease);
            if (status.IsSuccess()) Storage.Data->State = snapshot.State; return status;
        }
        public NativeSequenceReadOnly<T> AsReadOnly()
        {
            CheckRead();
            var view = new NativeSequenceReadOnly<T> { Storage = Storage, State = IsCreated ? Storage.Data->State : default, Revision = Storage.Revision, Ring = false };
#if ENABLE_UNITY_COLLECTIONS_CHECKS
            view.m_Safety = m_Safety;
#endif
            return view;
        }
        public NativeSequenceEnumerator<T> GetEnumerator()
        {
            CheckRead();
            var enumerator = new NativeSequenceEnumerator<T> { Storage = Storage, State = IsCreated ? Storage.Data->State : default, Revision = Storage.Revision, Index = -1, Ring = false, Reverse = true };
#if ENABLE_UNITY_COLLECTIONS_CHECKS
            enumerator.m_Safety = m_Safety;
#endif
            return enumerator;
        }
        public void Dispose()
        {
            if (!IsCreated) return; CheckWrite();
            if (Storage.BatchActive) DeterministicStatus.Invalidated.ThrowIfFailure();
#if ENABLE_UNITY_COLLECTIONS_CHECKS
            AtomicSafetyHandle.Release(m_Safety);
#endif
            Storage.Destroy();
        }
        [Conditional("ENABLE_UNITY_COLLECTIONS_CHECKS")]
        private void CheckRead()
        {
#if ENABLE_UNITY_COLLECTIONS_CHECKS
            if (IsCreated) AtomicSafetyHandle.CheckReadAndThrow(m_Safety);
#endif
        }
        [Conditional("ENABLE_UNITY_COLLECTIONS_CHECKS")]
        private void CheckWrite()
        {
#if ENABLE_UNITY_COLLECTIONS_CHECKS
            if (IsCreated) AtomicSafetyHandle.CheckWriteAndThrow(m_Safety);
#endif
        }

    }
